




"use strict";

const makeSerializable = require("../util/makeSerializable");
const NullDependency = require("./NullDependency");
























const getExportsWithDepth = (exportsDepth) =>
	
	function getExportsFromData(data, curDepth = 1) {
		if (curDepth > exportsDepth) {
			return null;
		}

		if (data && typeof data === "object") {
			if (Array.isArray(data)) {
				return data.length < 100
					? data.map((item, idx) => ({
							name: `${idx}`,
							canMangle: true,
							exports: getExportsFromData(item, curDepth + 1) || undefined
						}))
					: null;
			}

			
			const exports = [];

			for (const key of Object.keys(data)) {
				exports.push({
					name: key,
					canMangle: true,
					exports:
						getExportsFromData(
							
							(data[key]),
							curDepth + 1
						) || undefined
				});
			}

			return exports;
		}

		return null;
	};

class JsonExportsDependency extends NullDependency {
	




	constructor(data, exportsDepth) {
		super();
		
		this.data = data;
		
		this.exportsDepth = exportsDepth;
	}

	get type() {
		return "json exports";
	}

	




	getExports(moduleGraph) {
		return {
			exports: getExportsWithDepth(this.exportsDepth)(
				this.data &&  (this.data.get())
			),
			dependencies: undefined
		};
	}

	





	updateHash(hash, context) {
		this.data.updateHash(hash);
	}

	



	serialize(context) {
		context.write(this.data).write(this.exportsDepth);
		super.serialize(context);
	}

	



	deserialize(context) {
		this.data = context.read();
		const c1 = context.rest;
		this.exportsDepth = c1.read();
		super.deserialize(c1.rest);
	}
}

makeSerializable(
	JsonExportsDependency,
	"webpack/lib/dependencies/JsonExportsDependency"
);

module.exports = JsonExportsDependency;
